import { AevkoFloating } from '../shared/floating.directive';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  inject,
  booleanAttribute,
  computed,
  forwardRef,
  input,
  model,
  signal,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
export interface AevkoSelectItem {
  value: string;
  label: string;
  disabled?: boolean;
}
@Component({
  selector: 'aevko-select',
  standalone: true,
  imports: [AevkoFloating],
  templateUrl: './select.component.html',
  styleUrl: './select.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => AevkoSelect),
      multi: true,
    },
  ],
  host: {
    'data-slot': 'select',
    '(document:pointerdown)': 'dismissOutside($event)',
    '(document:focusin)': 'dismissOutside($event)',
    '[attr.data-disabled]': 'isDisabled() ? "true" : null',
  },
})
export class AevkoSelect implements ControlValueAccessor {
  private readonly hostElement = inject<ElementRef<HTMLElement>>(ElementRef);
  protected dismissOutside(event: Event): void {
    if (this.open() && !event.composedPath().includes(this.hostElement.nativeElement)) {
      this.open.set(false);
    }
  }

  readonly id = input('aevko-select');
  readonly label = input.required<string>();
  readonly placeholder = input('Select an option');
  readonly items = input.required<readonly AevkoSelectItem[]>();
  readonly value = model('');
  readonly disabled = input(false, { transform: booleanAttribute });
  protected readonly formDisabled = signal(false);
  protected readonly isDisabled = computed(() => this.disabled() || this.formDisabled());
  protected readonly open = signal(false);
  protected readonly active = signal(0);
  protected readonly enabledItems = computed(() => this.items().filter((item) => !item.disabled));
  protected readonly activeOption = computed(() => this.enabledItems()[this.active()]);
  protected readonly selected = computed(() =>
    this.items().find((item) => item.value === this.value()),
  );
  private onChange: (value: string) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  protected toggle(): void {
    if (this.isDisabled()) {
      return;
    }
    this.open.update((open) => !open);
    if (this.open()) {
      const selectedIndex = this.enabledItems().findIndex((item) => item.value === this.value());
      this.active.set(Math.max(0, selectedIndex));
    }
  }

  protected keydown(event: KeyboardEvent): void {
    const items = this.enabledItems();
    if (event.key === 'Escape') {
      this.open.set(false);
      return;
    }
    if (!['ArrowDown', 'ArrowUp', 'Enter', ' '].includes(event.key)) return;
    event.preventDefault();
    if (!this.open()) {
      this.open.set(true);
      return;
    }
    if (!items.length) {
      return;
    }
    if (event.key === 'Enter' || event.key === ' ') {
      const item = items[this.active()];
      if (item) this.choose(item);
    } else {
      this.active.update(
        (i) => (i + (event.key === 'ArrowUp' ? -1 : 1) + items.length) % items.length,
      );
    }
  }

  protected choose(item: AevkoSelectItem): void {
    if (!item.disabled) {
      this.value.set(item.value);
      this.onChange(item.value);
      this.onTouched();
      this.open.set(false);
    }
  }

  protected touch(): void {
    this.onTouched();
  }

  writeValue(value: string | null): void {
    this.value.set(value ?? '');
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(disabled: boolean): void {
    this.formDisabled.set(disabled);
    if (disabled) {
      this.open.set(false);
    }
  }
}

:host {
  display: inline-block;
  min-inline-size: 12rem;
  position: relative;
}
button {
  align-items: center;
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #a3a3a3);
  border-radius: 0;
  color: inherit;
  display: flex;
  inline-size: 100%;
  justify-content: space-between;
  min-block-size: 2.5rem;
  padding: 0.5rem 0.75rem;
}
button:focus-visible {
  outline: 2px solid var(--aevko-ring, #a3a3a3);
  outline-offset: 2px;
}
[role='listbox'] {
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #e4e4e7);
  box-shadow: var(--aevko-shadow, 0 4px 16px rgb(0 0 0 / 0.08));
  inline-size: 100%;
  inset-block-start: calc(100% + 0.25rem);
  padding: 0.25rem;
  position: absolute;
  z-index: 35;
}
[role='option'] {
  padding: 0.625rem;
}
[role='option']:hover,
[role='option'][data-active='true'] {
  background: var(--aevko-background, #f4f4f5);
}
[role='option'][aria-disabled='true'] {
  opacity: 0.45;
}
[role='option'][aria-selected='true'] {
  font-weight: 500;
}

[hidden] {
  display: none;
}

@media (prefers-reduced-motion: no-preference) {
  [data-slot='select-content']:not([hidden]) {
    animation: aevko-select-enter 140ms cubic-bezier(0.2, 0, 0, 1);
  }
  @keyframes aevko-select-enter {
    from {
      opacity: 0;
      translate: 0 3px;
    }
    to {
      opacity: 1;
      translate: 0 0;
    }
  }
}

import {
  afterEveryRender,
  DestroyRef,
  Directive,
  ElementRef,
  inject,
  input,
  booleanAttribute,
} from '@angular/core';

/** Keeps non-modal surfaces inside the viewport without changing focus ownership. */
@Directive({ selector: '[aevkoFloating]', standalone: true })
export class AevkoFloating {
  readonly aevkoFloating = input(true, { transform: booleanAttribute });
  private readonly element = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
  private readonly destroy = inject(DestroyRef);
  constructor() {
    afterEveryRender(() => this.position());
    const view = this.element.ownerDocument.defaultView;
    if (view) {
      const update = () => this.position();
      view.addEventListener('resize', update);
      view.addEventListener('scroll', update, true);
      this.destroy.onDestroy(() => {
        view.removeEventListener('resize', update);
        view.removeEventListener('scroll', update, true);
      });
    }
  }
  private position(): void {
    const panel = this.element;
    const view = panel.ownerDocument.defaultView;
    if (!view || panel.hidden || !this.aevkoFloating()) return;
    const anchor = panel.parentElement?.querySelector<HTMLElement>(
      '[data-slot$="trigger"], input, button',
    );
    if (!anchor) return;
    const rect = anchor.getBoundingClientRect();
    const margin = 8;
    const gap = 6;
    const width = view.innerWidth;
    const height = view.innerHeight;
    if (panel.getAttribute('role') === 'listbox') panel.style.width = `${rect.width}px`;
    panel.style.position = 'fixed';
    panel.style.inset = 'auto';
    panel.style.transform = 'none';
    panel.style.boxSizing = 'border-box';
    panel.style.maxWidth = `${width - margin * 2}px`;
    panel.style.maxHeight = `${height - margin * 2}px`;
    panel.style.overflow = 'auto';
    const size = panel.getBoundingClientRect();
    const side = panel.dataset['side'] ?? 'bottom';
    const align = panel.dataset['align'] ?? 'start';
    let x =
      align === 'end'
        ? rect.right - size.width
        : align === 'center'
          ? rect.left + (rect.width - size.width) / 2
          : rect.left;
    let y = rect.bottom + gap;
    if (side === 'top') y = rect.top - size.height - gap;
    if (side === 'left' || side === 'right') {
      x = side === 'left' ? rect.left - size.width - gap : rect.right + gap;
      y = rect.top;
    } else if (y + size.height > height - margin && rect.top > height - rect.bottom) {
      y = rect.top - size.height - gap;
    } else if (y < margin) y = rect.bottom + gap;
    panel.style.left = `${Math.max(margin, Math.min(x, width - size.width - margin))}px`;
    panel.style.top = `${Math.max(margin, Math.min(y, height - size.height - margin))}px`;
  }
}
